<?php require __DIR__.'/../app/bootstrap.php';require_login();$u=current_user($pdo);$q=$pdo->prepare('SELECT balance FROM wallets WHERE user_id=?');$q->execute([$u['id']]);$balance=(float)$q->fetchColumn();$q=$pdo->prepare('SELECT * FROM data_transactions WHERE user_id=? ORDER BY id DESC LIMIT 5');$q->execute([$u['id']]);$recent=$q->fetchAll();$q=$pdo->prepare('SELECT COALESCE(SUM(amount),0) FROM referrals WHERE referrer_id=? AND status="paid"');$q->execute([$u['id']]);$bonus=(float)$q->fetchColumn();require __DIR__.'/../app/layout.php';header_html('Dashboard');?><div class="hero card"><div><p class="eyebrow">Welcome back</p><h1><?=e($u['name'])?></h1><p>Buy data, airtime and pay supported bills from one wallet.</p></div><div class="balance"><?=money($balance)?></div></div><div class="grid four"><a class="card stat linkcard" href="/wallet.php"><span>Wallet</span><strong><?=money($balance)?></strong></a><a class="card stat linkcard" href="/buy-data.php"><span>Buy Data</span><strong>→</strong></a><a class="card stat linkcard" href="/buy-airtime.php"><span>Buy Airtime</span><strong>→</strong></a><a class="card stat linkcard" href="/bills.php"><span>Pay Bills</span><strong>→</strong></a></div><div class="grid two"><div class="card"><h3>Referral</h3><p>Your code: <strong><?=e($u['referral_code'])?></strong></p><p>Referral bonus earned: <?=money($bonus)?></p></div><div class="card"><h3>Recent data purchases</h3><?php if(!$recent):?><p class="muted">No transactions yet.</p><?php else:?><div class="table-wrap"><table><tr><th>Plan</th><th>Amount</th><th>Status</th></tr><?php foreach($recent as $r):?><tr><td><?=e($r['plan'])?></td><td><?=money($r['amount'])?></td><td><?=e($r['status'])?></td></tr><?php endforeach;?></table></div><?php endif;?></div></div><?php footer_html();
